import { THEMES_AREA, requestTheme } from '@hermes/plugin-sdk'

const ID = 'vaporware-theme'
const THEME_ID = 'manor-vaporware'
// The CLI/TUI skin is also named "vaporware". Desktop resolves a skin before a
// contributed theme of the same name, so when the skin is active we follow it
// to the full Desktop theme (fonts and terminal colors included).
const SKIN_NAME = 'vaporware'
const STYLE_ID = 'vaporware-theme-base'

const SANS = "'monofur', 'Hack', 'JetBrains Mono', Consolas, monospace"
const MONO = "'Hack', 'JetBrains Mono', 'Fira Code', Consolas, 'DejaVu Sans Mono', monospace"

const THEME = {
  name: THEME_ID,
  label: 'Vaporware',
  description: '80s retro vaporwave - monofur UI, Hack for chat and code',
  colors: {
    "background": "#0a0612",
    "foreground": "#e6dcff",
    "card": "#1a1030",
    "cardForeground": "#e6dcff",
    "muted": "#1a1030",
    "mutedForeground": "#8a7aa8",
    "popover": "#1a1030",
    "popoverForeground": "#e6dcff",
    "primary": "#ff2bd6",
    "primaryForeground": "#0a0612",
    "secondary": "#3d2a5c",
    "secondaryForeground": "#e6dcff",
    "accent": "#00f0ff",
    "accentForeground": "#0a0612",
    "border": "#3d2a5c",
    "input": "#3d2a5c",
    "ring": "#00f0ff",
    "midground": "#e6dcff",
    "midgroundForeground": "#0a0612",
    "composerRing": "#ff2bd6",
    "destructive": "#ff3860",
    "destructiveForeground": "#0a0612",
    "sidebarBackground": "#0d0818",
    "sidebarBorder": "#3d2a5c",
    "userBubble": "#2a1748",
    "userBubbleBorder": "#ff2bd6"
},
  typography: { fontSans: SANS, fontMono: MONO },
  terminal: {
    "background": "#0a0612",
    "foreground": "#e6dcff",
    "cursor": "#ff2bd6",
    "selectionBackground": "#3d2a5c",
    "black": "#0a0612",
    "red": "#ff3860",
    "green": "#39ff14",
    "yellow": "#ffe600",
    "blue": "#7b61ff",
    "magenta": "#ff2bd6",
    "cyan": "#00f0ff",
    "white": "#e6dcff",
    "brightBlack": "#8a7aa8",
    "brightRed": "#ff6b8b",
    "brightGreen": "#7dff5c",
    "brightYellow": "#fff27a",
    "brightBlue": "#a594ff",
    "brightMagenta": "#ff7ae6",
    "brightCyan": "#7af8ff",
    "brightWhite": "#ffffff"
}
}

const BASE_CSS = `@font-face{font-family:'Hack';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Hack';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Hack';font-style:italic;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Hack';font-style:italic;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
:root:is([data-hermes-theme^="manor-vaporware"], [data-hermes-theme="vaporware"]) :is(
  [data-slot='aui_thread-content'],
  [data-slot='composer-rich-input'],
  [data-tool-row],
  [data-tool-summary],
  pre, code, kbd, samp, .font-mono
) {
  font-family: ${MONO} !important;
}
:root:is([data-hermes-theme^="manor-vaporware"], [data-hermes-theme="vaporware"]) a {
  text-shadow: 0 0 7px rgba(0, 240, 255, 0.35);
}`

function installBaseStyle(ctx) {
  if (typeof document === 'undefined') return
  document.getElementById(STYLE_ID)?.remove()
  const style = document.createElement('style')
  style.id = STYLE_ID
  style.textContent = BASE_CSS
  document.head.append(style)
  ctx.onDispose(() => style.remove())
}

function followCliSkin(ctx) {
  if (typeof document === 'undefined' || typeof MutationObserver === 'undefined') return
  const root = document.documentElement
  const follow = () => {
    if ((root.dataset.hermesTheme ?? '') === SKIN_NAME) requestTheme(THEME_ID)
  }
  const observer = new MutationObserver(follow)
  observer.observe(root, { attributes: true, attributeFilter: ['data-hermes-theme'] })
  follow()
  ctx.onDispose(() => observer.disconnect())
}

export default {
  id: ID,
  name: 'Vaporware Theme',
  version: '0.1.0',
  description: 'Vaporware for Hermes Desktop - made for The Manor / Gizmo.',
  register(ctx) {
    ctx.registerMany([{
      id: THEME.name,
      area: THEMES_AREA,
      data: {
        ...THEME,
        colors: { ...THEME.colors },
        darkColors: { ...THEME.colors },
        typography: { ...THEME.typography },
        terminal: { ...THEME.terminal },
        darkTerminal: { ...THEME.terminal }
      }
    }])
    installBaseStyle(ctx)
    followCliSkin(ctx)
  }
}
